/* ================= AUDIO ================= */
const VOICEPACK={"da": [{"b64": "", "off": 0.12, "dur": 0.6089}, {"b64": "", "off": 0.0901, "dur": 0.5391}, {"b64": "", "off": 0.12, "dur": 0.579}], "dum": [{"b64": "", "off": 0.1, "dur": 0.579}, {"b64": "", "off": 0.0851, "dur": 0.6139}, {"b64": "", "off": 0.0901, "dur": 0.6688}, {"b64": "", "off": 0.0851, "dur": 0.8434}, {"b64": "", "off": 0.0901, "dur": 0.4892}]};
const TABLAPACK={"da": [{"b64": "", "off": 0.0, "dur": 0.38}], "dum": [{"b64": "", "off": 0.0, "dur": 0.82}]};
const SOUNDS=[
  {id:'tablarec',nm:'recorded tabla',ds:'real tabla — resonant "ta" for long, crisp "ti" for short'},
  {id:'rec',nm:'recorded voice',ds:'real "da" and "dum", several takes, placed exactly on the beat'},
  {id:'mine',nm:'your voice',ds:'record "dum" and "da" once — played back in time'},
  {id:'dumda',nm:'dum · da',ds:'sung syllables — long "dum", short "da"'},
  {id:'daada',nm:'daa · da',ds:'held vowel for long, clipped for short'},
  {id:'tabla',nm:'dhā · tā',ds:'tabla — bass stroke for long, rim for short'},
  {id:'tone',nm:'tone',ds:'plain low / high tones'}
];
const settings=store.get('settings',{sound:'tablarec',bpm:150});
if(!settings.v7){ settings.sound='tablarec'; settings.v7=1; store.set('settings',settings); }
if(!settings.v6){ settings.sound='rec'; settings.bpm=150; settings.v6=1; store.set('settings',settings); }
const A={ctx:null,out:null,noise:null,timers:[],
  ensure(){
    if(!this.ctx){const C=window.AudioContext||window.webkitAudioContext; if(!C)return false;
      this.ctx=new C();
      const comp=this.ctx.createDynamicsCompressor(); comp.threshold.value=-20; comp.knee.value=12; comp.ratio.value=5;
      const mk=this.ctx.createGain(); mk.gain.value=1.6;
      this.out=this.ctx.createGain(); this.out.gain.value=0.9; this.out.connect(comp); comp.connect(mk); mk.connect(this.ctx.destination);
      const len=Math.floor(this.ctx.sampleRate*1.0), b=this.ctx.createBuffer(1,len,this.ctx.sampleRate), d=b.getChannelData(0);
      for(let i=0;i<len;i++)d[i]=Math.random()*2-1; this.noise=b;
      /* small room: decaying stereo noise impulse */
      try{ const rl=Math.floor(this.ctx.sampleRate*1.1), ir=this.ctx.createBuffer(2,rl,this.ctx.sampleRate);
        for(let ch=0;ch<2;ch++){const x=ir.getChannelData(ch); for(let i=0;i<rl;i++) x[i]=(Math.random()*2-1)*Math.pow(1-i/rl,3.2);}
        const cv=this.ctx.createConvolver(); cv.buffer=ir; const wet=this.ctx.createGain(); wet.gain.value=0.22;
        this.voiceBus=this.ctx.createGain(); this.voiceBus.connect(this.out); this.voiceBus.connect(cv); cv.connect(wet); wet.connect(this.out);
      }catch(e){ this.voiceBus=this.out; }
      /* glottal pulse spectrum: harmonics falling ~12 dB/octave, like a relaxed singing voice */
      try{ const N=48, re=new Float32Array(N), im=new Float32Array(N); for(let k=1;k<N;k++) im[k]=Math.pow(k,-1.25)*(k%2?1:0.85);
        this.glottal=this.ctx.createPeriodicWave(re,im,{disableNormalization:false}); }catch(e){ this.glottal=null; }
      loadMine(); loadRec();}
    if(this.ctx.state==='suspended')this.ctx.resume();
    return true;
  },
  unlock(){ if(!this.ensure())return; try{const s=this.ctx.createBufferSource(); s.buffer=this.ctx.createBuffer(1,1,22050); s.connect(this.ctx.destination); s.start(0);}catch(e){} }
};
document.addEventListener('pointerdown',()=>A.unlock(),{once:true,passive:true});

function burst(t,freq,q,vol,dur,dest){
  const c=A.ctx, n=c.createBufferSource(); n.buffer=A.noise;
  const f=c.createBiquadFilter(); f.type='bandpass'; f.frequency.value=freq; f.Q.value=q;
  const g=c.createGain(); g.gain.setValueAtTime(vol,t); g.gain.exponentialRampToValueAtTime(0.0005,t+dur);
  n.connect(f); f.connect(g); g.connect(dest||A.dest||A.out); n.start(t); n.stop(t+dur+0.01);
}
/* sung syllable: glottal source → vowel formants, /d/ burst with pre-voicing, vibrato, breath, room.
   ctx.contour (0..1 position in the line) gives the phrase a gentle sung rise and fall. */
function voice(t,dur,isLong,style,vol,pos){
  const c=A.ctx, sound=Math.max(0.1,dur*0.9);
  const phrase = 1 + 0.05*Math.sin(Math.PI*Math.min(1,pos||0)) - (pos>0.92?0.04:0);
  const f0=(isLong?117:124)*phrase*(1+(Math.random()-0.5)*0.02);
  const osc=c.createOscillator(); if(A.glottal) osc.setPeriodicWave(A.glottal); else osc.type='sawtooth';
  osc.frequency.setValueAtTime(f0*0.97,t); osc.frequency.linearRampToValueAtTime(f0,t+0.06);
  osc.frequency.linearRampToValueAtTime(f0*(isLong?0.985:0.99),t+sound);
  /* vibrato that blooms on long notes */
  const lfo=c.createOscillator(), lg=c.createGain(); lfo.frequency.value=5.3+Math.random()*0.5;
  lg.gain.setValueAtTime(0,t); lg.gain.linearRampToValueAtTime(isLong?f0*0.014:f0*0.004,t+Math.min(0.35,sound));
  lfo.connect(lg); lg.connect(osc.frequency);
  const src=c.createGain(); osc.connect(src);
  /* breath */
  const br=c.createBufferSource(); br.buffer=A.noise; br.loop=true;
  const bf=c.createBiquadFilter(); bf.type='bandpass'; bf.frequency.value=1600; bf.Q.value=0.6;
  const bg=c.createGain(); bg.gain.value=0.05; br.connect(bf); bf.connect(bg); bg.connect(src);
  const env=c.createGain(); env.gain.value=0; env.connect(A.dest||A.voiceBus||A.out);
  const V = (style==='dumda'&&isLong) ? [{f:640,b:80,g:1},{f:1150,b:100,g:0.55},{f:2450,b:150,g:0.24},{f:3400,b:220,g:0.08}]
                                      : [{f:760,b:90,g:1},{f:1250,b:110,g:0.6},{f:2600,b:160,g:0.22},{f:3500,b:220,g:0.08}];
  const nodes=V.map(x=>{const bp=c.createBiquadFilter(); bp.type='bandpass'; bp.Q.value=x.f/x.b; bp.frequency.value=x.f;
    const g=c.createGain(); g.gain.value=x.g; src.connect(bp); bp.connect(g); g.connect(env); return {bp,g,x};});
  /* dental d: F1 rises from closure, F2 falls from ~1700 */
  nodes[0].bp.frequency.setValueAtTime(300,t); nodes[0].bp.frequency.linearRampToValueAtTime(V[0].f,t+0.05);
  nodes[1].bp.frequency.setValueAtTime(1700,t); nodes[1].bp.frequency.linearRampToValueAtTime(V[1].f,t+0.06);
  /* pre-voicing murmur (Urdu d is voiced through the closure) */
  const pv=c.createBiquadFilter(); pv.type='lowpass'; pv.frequency.value=320; const pg=c.createGain();
  pg.gain.setValueAtTime(0,t); pg.gain.linearRampToValueAtTime(0.9*vol,t+0.008); pg.gain.linearRampToValueAtTime(0,t+0.03);
  src.connect(pv); pv.connect(pg); pg.connect(env);
  const pk=(isLong?3.3:3.0)*vol;
  env.gain.setValueAtTime(0,t); env.gain.linearRampToValueAtTime(pk*0.35,t+0.012); env.gain.linearRampToValueAtTime(pk,t+0.04);
  if(style==='dumda' && isLong){                       /* close into a hummed m */
    const m=t+sound*0.55;
    nodes[0].bp.frequency.setValueAtTime(V[0].f,m); nodes[0].bp.frequency.linearRampToValueAtTime(260,m+0.06);
    [1,2,3].forEach(i=>{ nodes[i].g.gain.setValueAtTime(V[i].g,m); nodes[i].g.gain.linearRampToValueAtTime(0.02,m+0.06); });
    env.gain.setValueAtTime(pk,m); env.gain.linearRampToValueAtTime(pk*0.85,m+0.07);
    bg.gain.setValueAtTime(0.05,m); bg.gain.linearRampToValueAtTime(0.0,m+0.06);
  } else if(isLong){ env.gain.setValueAtTime(pk,t+sound*0.6); env.gain.linearRampToValueAtTime(pk*0.8,t+sound-0.05); }
  env.gain.setTargetAtTime(0,t+sound-0.04,0.03);
  const end=t+sound+0.25;
  osc.start(t); osc.stop(end); lfo.start(t); lfo.stop(end); br.start(t); br.stop(end);
  burst(t+0.004,3100,0.9,0.28*vol,0.018);
}
/* ---------- recorded voice pack ---------- */
function loadRec(){
  if(A.recP) return A.recP;
  const dec=o=>{ const bin=atob(o.b64), u=new Uint8Array(bin.length); for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);
    return new Promise((res)=>{ try{ const p=A.ctx.decodeAudioData(u.buffer,b=>res({buf:b,off:o.off,dur:o.dur}),()=>res(null)); if(p&&p.then)p.catch(()=>res(null)); }catch(e){res(null);} }); };
  A.recP=Promise.all([Promise.all(VOICEPACK.da.map(dec)),Promise.all(VOICEPACK.dum.map(dec)),Promise.all(TABLAPACK.da.map(dec)),Promise.all(TABLAPACK.dum.map(dec))])
    .then(([da,dum,tda,tdum])=>{ A.rec={da:da.filter(Boolean),dum:dum.filter(Boolean),last:{l:-1,s:-1}}; A.recT={da:tda.filter(Boolean),dum:tdum.filter(Boolean),last:{l:-1,s:-1}}; });
  return A.recP;
}
/* choose the take whose sounding length best fits the slot, never the same take twice running */
function recSound(t,dur,isLong,vol,pos,holdF){
  const R=settings.sound==='tablarec'?A.recT:A.rec; if(!R||!R.da.length||!R.dum.length) return voice(t,dur,isLong,'dumda',vol,pos);
  const pool=isLong?R.dum:R.da, key=isLong?'l':'s';
  let bi=0,bs=1e9; pool.forEach((k,j)=>{ const sc=Math.abs((k.dur-k.off)-dur*0.95)+(j===R.last[key]?0.2:0); if(sc<bs){bs=sc;bi=j;} });
  R.last[key]=bi; const k=pool[bi];
  const rate=1+0.02*Math.sin(Math.PI*Math.min(1,pos||0))-((pos||0)>0.9?0.02:0);
  const c=A.ctx, src=c.createBufferSource(); src.buffer=k.buf; src.playbackRate.value=rate;
  const g=c.createGain(); const start=Math.max(c.currentTime, t-k.off/rate);
  const hold=Math.min(k.dur/rate, k.off/rate+dur*0.95), fo=Math.min(0.05,hold/3);
  g.gain.setValueAtTime(vol,start); g.gain.setValueAtTime(vol,start+hold-fo); g.gain.linearRampToValueAtTime(0,start+hold);
  src.connect(g); g.connect(A.dest||A.voiceBus||A.out); src.start(start); src.stop(start+hold+0.02);
}
/* ---------- your own voice ---------- */
const mine={dum:null,da:null};
const hasMine=k=>!!mine[k]||!!store.get('mine_'+k,null);
function b64ToBuf(b64){ const bin=atob(b64), n=bin.length/2, out=new Float32Array(n);
  for(let i=0;i<n;i++){ let v=bin.charCodeAt(2*i)|(bin.charCodeAt(2*i+1)<<8); if(v>32767)v-=65536; out[i]=v/32768; }
  const buf=A.ctx.createBuffer(1,n,22050); buf.getChannelData(0).set(out); return buf; }
function bufToB64(f32){ let s=''; for(let i=0;i<f32.length;i++){ let v=Math.max(-1,Math.min(1,f32[i]))*32767|0; if(v<0)v+=65536; s+=String.fromCharCode(v&255,v>>8); } return btoa(s); }
function loadMine(){ ['dum','da'].forEach(k=>{ const b=store.get('mine_'+k,null); if(b){ try{ mine[k]=b64ToBuf(b); }catch(e){} } }); }
/* trim silence, normalise, resample to 22.05 kHz, cap at 1.2 s */
function prepClip(ab){
  const d=ab.getChannelData(0), sr=ab.sampleRate; let pk=0; for(let i=0;i<d.length;i++) pk=Math.max(pk,Math.abs(d[i]));
  if(pk<0.02) return null;
  let a=0; while(a<d.length && Math.abs(d[a])<pk*0.12) a++; a=Math.max(0,a-Math.floor(sr*0.012));
  let z=d.length-1; while(z>a && Math.abs(d[z])<pk*0.06) z--; z=Math.min(d.length-1,z+Math.floor(sr*0.05));
  const ratio=sr/22050, n=Math.min(Math.floor((z-a)/ratio), 22050*1.2|0), out=new Float32Array(n);
  for(let i=0;i<n;i++) out[i]=d[a+Math.floor(i*ratio)]*(0.9/pk);
  const f=Math.min(n,Math.floor(22050*0.03)); for(let i=0;i<f;i++) out[n-1-i]*=i/f;   /* soft tail */
  return out;
}
function saveClip(k,f32){ const b=bufToB64(f32); store.set('mine_'+k,b); mine[k]=b64ToBuf(b); renderSoundOpts(); }
async function recordClip(k){
  A.ensure(); const st=$('recStatus');
  if(!navigator.mediaDevices||!window.MediaRecorder){ st.textContent='Recording isn\'t available here — use "choose files" instead.'; return; }
  let stream; try{ stream=await navigator.mediaDevices.getUserMedia({audio:true}); }
  catch(e){ st.textContent='Microphone blocked here — use "choose files" (a voice memo works).'; return; }
  const rec=new MediaRecorder(stream), chunks=[]; rec.ondataavailable=e=>chunks.push(e.data);
  rec.onstop=async()=>{ stream.getTracks().forEach(t=>t.stop());
    try{ const ab=await A.ctx.decodeAudioData(await new Blob(chunks).arrayBuffer()); const clip=prepClip(ab);
      if(!clip){ st.textContent='That was silent — try again a bit closer to the mic.'; return; }
      saveClip(k,clip); st.textContent='Saved "'+k+'". '+(mine.dum&&mine.da?'Both done — listen:':'Now record the other one.');
      if(mine.dum&&mine.da){ settings.sound='mine'; store.set('settings',settings); renderSoundOpts(); play(['l','s','l','l','s','l']); }
    }catch(e){ st.textContent='Couldn\'t read that recording — try "choose files".'; } };
  st.textContent='● Recording — say "'+k+'" now…'; rec.start(); setTimeout(()=>rec.state!=='inactive'&&rec.stop(),1400);
}
async function fileClip(k,input){ A.ensure(); const st=$('recStatus'); const f=input.files&&input.files[0]; if(!f) return;
  try{ const ab=await A.ctx.decodeAudioData(await f.arrayBuffer()); const clip=prepClip(ab);
    if(!clip){ st.textContent='That file seems silent.'; return; } saveClip(k,clip); st.textContent='Loaded "'+k+'".'; }
  catch(e){ st.textContent='Couldn\'t decode that file — try an m4a, mp3 or wav.'; } }
function mineSound(t,dur,isLong,vol){
  const buf=isLong?(mine.dum||mine.da):(mine.da||mine.dum); if(!buf) return voice(t,dur,isLong,'dumda',vol,0);
  const c=A.ctx, s=c.createBufferSource(); s.buffer=buf; const g=c.createGain();
  const hold=Math.min(buf.duration,dur*0.93);
  g.gain.setValueAtTime(vol,t); g.gain.setValueAtTime(vol,t+Math.max(0.02,hold-0.04)); g.gain.linearRampToValueAtTime(0,t+hold);
  s.connect(g); g.connect(A.dest||A.voiceBus||A.out); s.start(t); s.stop(t+hold+0.02);
}
function tabla(t,dur,isLong,vol){
  const c=A.ctx, f=isLong?311:370, decay=isLong?Math.min(0.7,dur*1.1):Math.min(0.2,dur*0.9);
  [1,2,3,4.15].forEach((h,i)=>{const o=c.createOscillator(); o.type='sine'; o.frequency.value=f*h;
    const g=c.createGain(); const d=decay/(1+i*0.7); g.gain.setValueAtTime(0,t); g.gain.linearRampToValueAtTime(0.55*vol/(i+1),t+0.004);
    g.gain.exponentialRampToValueAtTime(0.0006,t+d); o.connect(g); g.connect(A.dest||A.out); o.start(t); o.stop(t+d+0.05);});
  burst(t,isLong?2400:4200,1.2,0.35*vol,0.015);
  if(isLong){ const o=c.createOscillator(); o.type='sine'; o.frequency.setValueAtTime(72,t); o.frequency.linearRampToValueAtTime(104,t+Math.min(0.45,dur));
    const g=c.createGain(); g.gain.setValueAtTime(0,t); g.gain.linearRampToValueAtTime(1.1*vol,t+0.006); g.gain.exponentialRampToValueAtTime(0.0006,t+Math.min(0.9,dur*1.4));
    o.connect(g); g.connect(A.dest||A.out); o.start(t); o.stop(t+1); }
}
function tone(t,dur,isLong,vol){
  const c=A.ctx,o=c.createOscillator(),g=c.createGain(); o.type='triangle'; o.frequency.value=isLong?392:587;
  g.gain.setValueAtTime(0,t); g.gain.linearRampToValueAtTime(0.8*vol,t+0.01); g.gain.exponentialRampToValueAtTime(0.0005,t+dur*0.9);
  o.connect(g); g.connect(A.dest||A.out); o.start(t); o.stop(t+dur);
}
function tick(){ if(!A.ensure())return; const t=A.ctx.currentTime+0.005; burst(t,2600,2,0.5,0.03,A.out); }
function syllableSound(t,dur,isLong,vol,pos,hold){
  const s=settings.sound, d=dur*(hold||1);
  if(s==='tabla') tabla(t,d,isLong,vol); else if(s==='tone') tone(t,d,isLong,vol);
  else if(s==='mine') mineSound(t,d,isLong,vol); else if(s==='rec'||s==='tablarec') recSound(t,d/0.95,isLong,vol,pos,hold); else voice(t,d,isLong,s,vol,pos);
}
/* soft low drum on each foot's first syllable */
function footThump(t,vol){ const c=A.ctx,o=c.createOscillator(),g=c.createGain(); o.type='sine';
  o.frequency.setValueAtTime(95,t); o.frequency.exponentialRampToValueAtTime(58,t+0.18);
  g.gain.setValueAtTime(0,t); g.gain.linearRampToValueAtTime(0.5*vol,t+0.006); g.gain.exponentialRampToValueAtTime(0.0005,t+0.3);
  o.connect(g); g.connect(A.dest||A.out); o.start(t); o.stop(t+0.32); }
function stopAll(){ A.timers.forEach(clearTimeout); A.timers=[];
  if(A.ctx && A.sess){ const g=A.sess, now=A.ctx.currentTime; try{ g.gain.cancelScheduledValues(now); g.gain.setValueAtTime(g.gain.value,now); g.gain.linearRampToValueAtTime(0,now+0.03); }catch(e){}
    setTimeout(()=>{ try{g.disconnect();}catch(e){} },80); A.sess=null; } }
/* seq of 'l','s','x','c'; onStep(i) fires as each syllable sounds */
function play(seq,opts){
  opts=opts||{}; if(!A.ensure())return 0;
  if((settings.sound==='rec'||settings.sound==='tablarec') && !A.rec){ loadRec().then(()=>play(seq,opts)); return (seq.length*1.5*60/settings.bpm); }
  stopAll();
  const sess=A.ctx.createGain(); sess.gain.value=1; sess.connect(settings.sound==='tablarec'?A.out:(A.voiceBus||A.out)); A.sess=sess; /* tabla samples carry their own room: skip reverb */ A.dest=sess;
  const beat=60/(opts.bpm||settings.bpm); let t=A.ctx.currentTime+0.16; const t0=t;
  const F=opts.feet, cae=opts.cae||[];
  seq.forEach((v,i)=>{
    const isLong=(v==='l'||v==='x'); let dur=(isLong?2:1)*beat;
    let vol=v==='c'?0.45:1, hold=0.97;
    if(F){ const fs=(i===0||F[i]!==F[i-1]), fe=(i===seq.length-1||F[i+1]!==F[i]);
      if(fs && i>0 && cae.includes(F[i])) t+=beat*0.6;              /* breath at the mid-line break */
      else if(fs && i>0) t+=beat*(settings.footGap!=null?settings.footGap:0.5); /* short rest between feet */
      if(fs && settings.footPulse!==false && v!=='c') footThump(t,0.9);
      if(!fs && v!=='c') vol*=0.84;                                   /* stress the foot's first syllable */
      if(fe && i<seq.length-1){ dur*=1.07; hold=0.82; }               /* a little lift at the end of each foot */
    }
    if(opts.cadence!==false && i===seq.length-1 && seq.length>4){ dur*=1.4; if(settings.sound==='tablarec') hold=0.6; } /* no long ring on the final tabla stroke */
    if(!(v==='c' && settings.sound==='tablarec')) syllableSound(t,dur,isLong,vol,i/Math.max(1,seq.length-1),hold); /* extrametrical syllable: no stroke on tabla */
    if(opts.onStep) A.timers.push(setTimeout(()=>opts.onStep(i),(t-A.ctx.currentTime)*1000));
    t+=dur;
  });
  if(opts.onEnd) A.timers.push(setTimeout(opts.onEnd,(t-A.ctx.currentTime)*1000+60));
  return (t-t0);
}
function litter(nodes){ return i=>{ nodes.forEach(n=>n.classList.remove('lit')); const n=nodes[i]; if(n){n.classList.add('lit'); setTimeout(()=>n.classList.remove('lit'),240);} }; }

/* sound sheet */
function openSound(){ renderSoundOpts(); if($('soundSheet')) $('soundSheet').classList.add('on'); }
function closeSound(){ if($('soundSheet')) $('soundSheet').classList.remove('on'); }
function renderSoundOpts(){
  const sOpts = $('soundOpts');
  if (sOpts) {
    sOpts.innerHTML=SOUNDS.map(s=>`<div class="sopt ${s.id===settings.sound?'on':''}" onclick="pickSound('${s.id}')"><span class="play">▶︎</span><div style="flex:1"><div class="nm">${s.nm}</div><div class="ds">${s.ds}</div></div></div>`
      + (s.id==='mine'?`<div class="card" style="margin:-2px 0 10px;padding:10px 12px" onclick="event.stopPropagation()">
        <div class="row" style="margin:0">
          <button class="btn sm ${hasMine('dum')?'':'gold'}" onclick="recordClip('dum')">● dum ${hasMine('dum')?'✓':''}</button>
          <button class="btn sm ${hasMine('da')?'':'gold'}" onclick="recordClip('da')">● da ${hasMine('da')?'✓':''}</button>
          <label class="btn sm ghost">dum file<input type="file" accept="audio/*" style="display:none" onchange="fileClip('dum',this)"></label>
          <label class="btn sm ghost">da file<input type="file" accept="audio/*" style="display:none" onchange="fileClip('da',this)"></label>
        </div>
        <p class="tiny muted" id="recStatus" style="margin:6px 0 0">Tap ● and say the syllable once, the way you'd recite — short and clear for "da", a full "dum" for the long. Silence is trimmed automatically; it stays on this device.</p></div>`:'')).join('');
  }
  if ($('bpm')) $('bpm').value=settings.bpm;
  if ($('bpmV')) $('bpmV').textContent=settings.bpm;
}
function pickSound(id){
  if(id==='mine' && !(hasMine('dum')||hasMine('da'))){
    settings.sound=id; store.set('settings',settings); renderSoundOpts();
    const st=$('recStatus'); if(st) st.textContent='Record "dum" and "da" first (or choose two audio files).';
    return;
  }
  settings.sound=id; store.set('settings',settings); renderSoundOpts();
  if($('soundName')) $('soundName').textContent=SOUNDS.find(s=>s.id===id).nm.replace(/ /g,'');
  play(['l','s','l','l','s','l']);
}
function footGapSecs(){ return (settings.footGap!=null?settings.footGap:0.5)*60/settings.bpm; }
function renderFootGapV(){ const el=$('footGapV'); if(el) el.textContent=(+settings.footGap).toFixed(2)+' beat ('+footGapSecs().toFixed(2)+'s)'; }
function setBpm(v){ settings.bpm=+v; store.set('settings',settings);
  [['bpm','bpmV'],['bpmHdr','bpmHdrV']].forEach(([i,o])=>{ const el=$(i); if(el){ el.value=settings.bpm; const elO=$(o); if(elO) elO.textContent=settings.bpm; } });
  renderFootGapV(); }
if($('bpm')) $('bpm').addEventListener('input',e=>setBpm(e.target.value));
if($('bpmHdr')){ $('bpmHdr').addEventListener('input',e=>setBpm(e.target.value)); setBpm(settings.bpm); }
if(settings.footGap==null) settings.footGap=0.5;
if($('footGap')) {
  $('footGap').value=settings.footGap;
  $('footGap').addEventListener('input',e=>{ settings.footGap=+e.target.value; renderFootGapV(); store.set('settings',settings); });
}
renderFootGapV();
if($('soundName')) $('soundName').textContent=SOUNDS.find(s=>s.id===settings.sound).nm.replace(/ /g,'');


